proof.r:
.libPaths(c(path.expand("~/R/library"), .libPaths()))
suppressPackageStartupMessages(library(slider))
suppressPackageStartupMessages(library(jsonlite))
x <- c(1, 5, 3, 2, 6, 10)
y <- c(2, 4, 1, 3, 5, 7)
i <- c(0, 1, 3, 4, 6, 8)
ch <- c("a", "b", "c", "d", "e", "f")
lg <- c(TRUE, FALSE, TRUE, TRUE, FALSE, TRUE)
json_val <- function(value) {
  if (is.character(value)) {
    toJSON(value, auto_unbox = FALSE)
  } else {
    toJSON(as.numeric(value), auto_unbox = FALSE, digits = 17, na = "null")
  }
}

one <- function() {
  as.numeric(unlist(slide(x, function(w) w, .before = 1)))
}
value <- one()
elapsed <- numeric(20)
for (step_i in seq_len(20)) {
  t0 <- as.numeric(Sys.time())
  one()
  elapsed[[step_i]] <- as.numeric(Sys.time()) - t0
}
cat(sprintf('{"value":%s,"median_ms":%.17g}\n', json_val(value), median(elapsed) * 1000))

proof.python:
import json, math, statistics, time
from slider import *
x = [1, 5, 3, 2, 6, 10]
y = [2, 4, 1, 3, 5, 7]
i = [0, 1, 3, 4, 6, 8]
ch = ["a", "b", "c", "d", "e", "f"]
lg = [True, False, True, True, False, True]
def flat(value):
    if value and isinstance(value[0], list):
        out = []
        for item in value:
            out.extend(flat(item) if item else [])
        return out
    out = []
    for item in value:
        if isinstance(item, bool):
            out.append(int(item))
        elif isinstance(item, float) and math.isnan(item):
            out.append(None)
        else:
            out.append(item)
    return out

def one():
    return flat(slide(x, lambda w: w, before=1))

value = one()
elapsed = []
for _ in range(20):
    started = time.perf_counter()
    one()
    elapsed.append((time.perf_counter() - started) * 1000)
print(json.dumps({"value": value, "median_ms": statistics.median(elapsed)}))

